"""In-memory event hub: per-run event list and condition variable for SSE streaming and replay."""
import asyncio
import json
from typing import Any


class Stream:
    def __init__(self, replay: bool = False):
        self.events: list[dict[str, Any]] = []
        self.done = False
        self.cond = asyncio.Condition()
        self.replay = replay
        self.rails = None
        self.task = None

    async def publish(self, etype: str, data: dict[str, Any], t: float | None = None):
        async with self.cond:
            self.events.append({"type": etype, "data": data, "t": t, "replay": self.replay})
            self.cond.notify_all()

    async def finish(self):
        async with self.cond:
            self.done = True
            self.cond.notify_all()

    async def iterate(self):
        i = 0
        while True:
            async with self.cond:
                await self.cond.wait_for(lambda: i < len(self.events) or self.done)
                batch = self.events[i:]
                i = len(self.events)
                finished = self.done
            for ev in batch:
                yield {"event": "ev", "data": json.dumps(ev)}
            if finished and i >= len(self.events):
                yield {"event": "end", "data": "{}"}
                return


class Hub:
    def __init__(self):
        self.streams: dict[str, Stream] = {}

    def create(self, run_id: str, replay: bool = False) -> Stream:
        s = Stream(replay)
        self.streams[run_id] = s
        return s

    def get(self, run_id: str) -> Stream | None:
        return self.streams.get(run_id)

    def remove(self, run_id: str) -> None:
        self.streams.pop(run_id, None)

    def clear(self) -> None:
        self.streams.clear()

"""FastAPI app for Pocket Startup: REST APIs + SSE event streaming.

Bound strictly to 127.0.0.1.
Protects against path traversal and secret leakage.
The server never writes to committed evidence or evidence/metrics.json.
"""
import asyncio
from contextlib import asynccontextmanager
import hashlib
import json
from pathlib import Path
import re
import subprocess
import sys
from typing import Any

from fastapi import FastAPI, HTTPException, Query
from fastapi.responses import FileResponse, HTMLResponse
from pydantic import BaseModel
from sse_starlette.sse import EventSourceResponse

import config
