/* Pocket Startup Styles
   Brutalist retro-paper design without gradients.
   Reuses CSS variables and palette from docs/design/landing_reference.html.
   Readable body font, pixel look for headings only. System fallbacks only (offline).
*/
:root {
  --paper: #F6F1E7;
  --paper2: #FFFDF8;
  --paper3: #EDE3CF;
  --ink: #0F1226;
  --ink2: #454963;
  --red: #E5322D;
  --red-d: #CF2A25;
  --green: #2FB36B;
  --green-d: #1B8548;
  --amber: #F2B63D;
  --teal: #2E8F8B;
  --coral: #EF6F5E;
  --plum: #5E3A63;
  --sky: #4DA3FF;
  --shadow: 4px 4px 0 var(--ink);
  --shadow-sm: 2px 2px 0 var(--ink);
  --r: 4px;

  /* Offline typography with system fallbacks */
  --font-d: 'Pixelify Sans', 'Press Start 2P', 'Courier New', monospace;
  --font-b: 'Space Grotesk', system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --font-m: 'JetBrains Mono', 'Cascadia Code', 'Consolas', 'Courier New', monospace;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  background-color: var(--paper);
  color: var(--ink);
  font: 400 15px/1.45 var(--font-b);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5 {
  font-family: var(--font-d);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin: 0 0 10px;
}

p {
  margin: 0 0 10px;
}

code, pre, .mono {
  font-family: var(--font-m);
}

/* ================= Top Bar ================= */
.top-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  padding: 10px 16px;
