/* Pixel Office canvas for Pocket Startup
   Reuses sprite matrices and palette directly from docs/design/landing_reference.html.
   Reacts to real SSE events from /api/runs/{id}/events.
*/
(function () {
  const W = 500, H = 280;

  // Helper to compile palette-indexed string rows into offscreen canvas
  function mk(rows, pal) {
    const w = Math.max(...rows.map(r => r.length)), h = rows.length;
    const c = document.createElement('canvas');
    c.width = w; c.height = h;
    const g = c.getContext('2d');
    rows.forEach((r, y) => {
      for (let x = 0; x < r.length; x++) {
        const k = r[x];
        if (pal[k]) {
          g.fillStyle = pal[k];
          g.fillRect(x, y, 1, 1);
        }
      }
    });
    return c;
  }

  const R16 = s => (s + '................').slice(0, 16);
  const BASE = [
    '................',
    '.....KKKKKK.....',
    '....KHHHHHHK....',
    '...KHHHHHHHHK...',
    '...KHSSSSSSHK...',
    '...KSSSSSSSSK...',
    '...KSKSSSSKSK...',
    '...KSSSSSSSSK...',
    '...KSSSMMSSSK...',
    '....KSSSSSSK....',
    '...KKTTTTTTKK...',
    '..KTTTTTTTTTTK..',
    '..KTTTTTTTTTTK..',
    '..KSTTTTTTTTSK..',
    '..KSTTTTTTTTSK..',
    '...KTTTTTTTTK...',
    '...KPPPPPPPPK...',
    '...KPPPKKPPPK...',
    '...KPPK..KPPK...',
    '..KKKK....KKKK..'
  ];

  const over = (rows, m) => {
    const r = rows.slice();
    for (const k in m) r[+k] = R16(m[k]);
    return r;
  };

  const ARMS_UP = {
    11: '..SK' + 'T'.repeat(10) + 'KS',
    13: '..K' + 'T'.repeat(10) + 'K',
    14: '..K' + 'T'.repeat(10) + 'K'
  };

  const PAL = { K: '#0F1226', M: '#B5473F' };

  // Sprite rows from landing_reference.html
  const founderRows = over(BASE, { 4: '..KHHHHHHHHHHHK' });
  const engRows = over(BASE, { 3: '..KAK' + 'HHHHHH' + 'KAK', 4: '..KAK' + 'HSSSSH' + 'KAK', 5: '..KAK' + 'SSSSSS' + 'KAK' });
  const testRows = over(BASE, { 13: '..KSTTTTTTTTSK', 14: '..KATTTTTTTTSK' });
  const cfoRows = over(BASE, { 11: '..K' + 'TTTTAATTTT' + 'K', 12: '..K' + 'TTTTAATTTT' + 'K', 13: '..KS' + 'TTTAATTT' + 'SK', 14: '..KS' + 'TTTAATTT' + 'SK' });

  // Sprites
  const SP = {
    founder: {
      idle: mk(founderRows, { ...PAL, H: '#E5322D', S: '#F2C9A0', T: '#4DA3FF', P: '#5E3A63', A: '#F2B63D', D: '#D9A878' }),
      react: mk(over(founderRows, { ...ARMS_UP, 8: '...KSSMMMMSSK' }), { ...PAL, H: '#E5322D', S: '#F2C9A0', T: '#4DA3FF', P: '#5E3A63', A: '#F2B63D', D: '#D9A878' })
    },
    eng: {
      idle: mk(engRows, { ...PAL, H: '#3B2A4D', S: '#E8B88A', T: '#2E8F8B', P: '#14383A', A: '#F2B63D', D: '#C4905F' }),
      react: mk(over(engRows, { 6: '..' + 'D'.repeat(10) + 'K', 8: '...KSSSSSSSSK' }), { ...PAL, H: '#3B2A4D', S: '#E8B88A', T: '#2E8F8B', P: '#14383A', A: '#F2B63D', D: '#B07A4C' })
    },
    tester: {
      idle: mk(testRows, { ...PAL, H: '#5A3A2A', S: '#C98D63', T: '#2FB36B', P: '#2B3358', A: '#E5322D', D: '#A8704A' }),
      react: mk(over(testRows, { ...ARMS_UP, 8: '...KSSMMMMSSK' }), { ...PAL, H: '#5A3A2A', S: '#C98D63', T: '#2FB36B', P: '#2B3358', A: '#E5322D', D: '#A8704A' })
    },
    cfo: {
      idle: mk(cfoRows, { ...PAL, H: '#8A8FA8', S: '#F2C9A0', T: '#2B3358', P: '#14183A', A: '#E5322D', D: '#D9A878' }),
      react: mk(over(cfoRows, { ...ARMS_UP, 8: '...KSSMMMMSSK' }), { ...PAL, H: '#8A8FA8', S: '#F2C9A0', T: '#2B3358', P: '#14183A', A: '#E5322D', D: '#D9A878' })
    }
  };

  const REC = [
    '................',
    '...KKKKKKKKKK...',
    '...KLLLLLLLLK...',
    '...KOOOOOOOOK...',
    '...KOWWWWWWOK...',
    '...KOOOOOOOOK...',
    '...KOOORROOOK...',
    '...KOOOOOOOOK...',
    '...KDDDDDDDDK...',
    '...KKKKKKKKKK...',
    '..KKKKKKKKKKKK..',
    '..KGGGGGGGGGGK..',
    '..KGGKKKKKKGGK..',
    '..KGGGGGGGGGGK..',
    '..KKKKKKKKKKKK..'
  ];
  const recPal = r => ({ K: '#0F1226', L: '#FFC27A', O: '#F2862B', D: '#C0611A', W: '#FFFDF8', R: r, G: '#8A8FA8' });
  SP.rec = {
    dim: mk(REC, recPal('#6E2420')),
    on: mk(REC, recPal('#FF4A3D'))
  };

  SP.laptop = mk([
    '..KKKKKKKKKKKK..',
    '..KNNNNNNNNNNK..',
    '..KNNYNNNNNYNK..',
    '..KNNNNNNNNNNK..',
    '..KNNNNNYNNNNK..',
    '..KNNNNNNNNNNK..',
    '..KKKKKKKKKKKK..',
    '.KWWWWWWWWWWWWK.',
    '.KWKWKWKWKWKWWK.',
    '.KKKKKKKKKKKKKK.'
  ], { K: '#0F1226', N: '#1E3F8A', Y: '#F2B63D', W: '#FFFFFF' });

  const WB_BUILDINGS = [
    [202, 14, 26, '#2E8F8B'],
    [218, 12, 40, '#EF6F5E'],
    [232, 16, 22, '#5E3A63'],
    [250, 10, 34, '#F2B63D'],
    [262, 16, 48, '#4DA3FF'],
    [282, 12, 30, '#2FB36B'],
    [296, 16, 40, '#EF6F5E'],
    [310, 6, 24, '#2E8F8B']
  ];
  const CONFETTI_COLORS = ['#E5322D', '#F2B63D', '#2FB36B', '#4DA3FF', '#EF6F5E', '#5E3A63'];

  class PixelOffice {
    constructor(canvas) {
      this.cv = canvas;
      this.ctx = canvas.getContext('2d');
      this.ctx.imageSmoothingEnabled = false;

      this.t = 0;
      this.last = performance.now();

      this.reset();
      requestAnimationFrame(n => this.frame(n));
    }

    reset() {
      this.idea = '';
      this.spec = null;
      this.attempt = 0;
      this.maxAttempts = 4;
      this.typing = false;
      this.facepalm = false;

      // Positions
      this.founderPos = { x: 42, y: 165 };
      this.founderBubble = null;
      this.founderReact = false;

      this.engPos = { x: 170, y: 126 };
      this.codeLines = 0;

      this.testerHome = 352;
      this.testerPos = { x: 352, y: 175 };
      this.testerTarget = 352;
      this.testerReact = false;
      this.testerClipboard = false;

      this.cfoHome = 520;
      this.cfoPos = { x: 520, y: 177 };
      this.cfoTarget = 520;
      this.cfoReact = false;
      this.cfoVisible = false;

      // Alarms & effects
      this.alarmColor = '#7B7F99';
      this.alarmGlow = null;
      this.alarmDuration = 0;

      this.shakeDuration = 0;
      this.errorBubble = null;

      this.recLit = 0;
      this.crashReport = null;
      this.patchTag = null;

      this.passStamp = false;
      this.passStampDuration = 0;

      this.verdictStamp = null;
      this.verdictDuration = 0;

      this.confetti = [];
      this.statusText = 'idle';
    }

    burst() {
      for (let i = 0; i < 46; i++) {
        this.confetti.push({
          x: 170 + Math.random() * 150,
          y: 40 + Math.random() * 30,
          vx: (Math.random() - 0.5) * 80,
          vy: Math.random() * 50 + 40,
          c: CONFETTI_COLORS[i % CONFETTI_COLORS.length],
          life: 2.5
        });
      }
    }

    handle(type, d) {
      d = d || {};
      switch (type) {
        case 'run_started':
          this.reset();
          this.idea = d.idea || 'an app idea';
          this.founderBubble = this.idea;
          this.founderReact = true;
          this.statusText = 'planning';
          setTimeout(() => { this.founderReact = false; }, 2000);
          break;

        case 'plan':
          this.spec = d.product_name || d.template || 'Spec ready';
          this.statusText = 'building';
          break;

        case 'attempt_started':
          this.attempt = d.n || 1;
          this.maxAttempts = d.of || 4;
          this.typing = true;
          this.facepalm = false;
          this.testerTarget = this.testerHome;
          this.testerClipboard = false;
          this.statusText = `attempt ${this.attempt}`;
          break;

        case 'code_written':
          this.typing = true;
          this.codeLines = Math.min(24, Math.floor((d.bytes || 500) / 100));
          this.statusText = 'verifying';
          break;

        case 'check_started':
          this.typing = false;
          this.testerClipboard = true;
          this.testerTarget = 236; // Walk over to engineer workstation
          this.statusText = 'browser test running';
          break;

        case 'check_failed':
          this.alarmColor = '#FF4A3D';
          this.alarmGlow = 'rgba(255,74,61,0.35)';
          this.alarmDuration = 2.8;
          this.shakeDuration = 0.45;
          this.testerReact = true;
          this.errorBubble = `${d.test || 'check failed'}: ${String(d.actual || 'error').slice(0, 36)}`;
          this.statusText = 'check failed';
          setTimeout(() => { this.testerReact = false; }, 1800);
          break;

        case 'autopsy':
          this.recLit = 3.5;
          this.crashReport = {
            root: d.root_cause ? d.root_cause.slice(0, 32) : 'handler crash',
            change: d.recommended_prompt_change ? d.recommended_prompt_change.slice(0, 32) : 'rule added'
          };
          this.statusText = 'diagnosing';
          break;

        case 'retry':
          this.facepalm = true;
          this.patchTag = '+1 prompt rule';
          this.errorBubble = null;
          this.statusText = 'retrying';
          setTimeout(() => { this.facepalm = false; this.patchTag = null; }, 2200);
          break;

        case 'check_passed':
          this.alarmColor = '#2FD07A';
          this.alarmGlow = 'rgba(47,208,122,0.35)';
          this.alarmDuration = 3.0;
          this.passStamp = true;
          this.passStampDuration = 3.5;
          this.typing = false;
          this.testerTarget = this.testerHome;
          this.testerClipboard = false;
          this.errorBubble = null;
          this.crashReport = null;
          this.burst();
          this.statusText = 'checks passed';
          break;

        case 'awaiting_approval':
          this.founderBubble = 'Approve this build?';
          this.founderReact = true;
          this.statusText = 'awaiting approval';
          break;

        case 'approved':
          this.founderBubble = 'Approved ✔';
          this.founderReact = true;
          this.burst();
          this.statusText = 'approved';
          setTimeout(() => { this.founderBubble = null; this.founderReact = false; }, 3000);
          break;

        case 'metrics_ready':
          this.cfoVisible = true;
          this.cfoTarget = 366;
          this.cfoReact = true;
          setTimeout(() => { this.cfoReact = false; }, 2500);
          break;

        case 'verdict_ready':
          this.verdictStamp = d.verdict || 'BUILD';
          this.verdictDuration = 5.0;
          this.cfoVisible = true;
          this.cfoTarget = 366;
          break;

        case 'run_finished':
          this.typing = false;
          this.statusText = d.success ? 'passed' : 'finished';
          break;
      }
    }

    frame(now) {
      const dt = Math.min(0.05, (now - this.last) / 1000);
      this.last = now;
      this.t += dt;

      this.update(dt);
      this.draw();
      requestAnimationFrame(n => this.frame(n));
    }

    update(dt) {
      // Tester walking interpolation
      if (Math.abs(this.testerPos.x - this.testerTarget) > 1) {
        const dir = Math.sign(this.testerTarget - this.testerPos.x);
        this.testerPos.x += dir * 90 * dt;
      } else {
        this.testerPos.x = this.testerTarget;
      }

      // CFO walking interpolation
      if (this.cfoVisible) {
        if (Math.abs(this.cfoPos.x - this.cfoTarget) > 1) {
          const dir = Math.sign(this.cfoTarget - this.cfoPos.x);
          this.cfoPos.x += dir * 85 * dt;
        } else {
          this.cfoPos.x = this.cfoTarget;
        }
      }

      // Timer updates
      this.shakeDuration = Math.max(0, this.shakeDuration - dt);
      this.alarmDuration = Math.max(0, this.alarmDuration - dt);
      if (this.alarmDuration === 0) {
        this.alarmColor = '#7B7F99';
        this.alarmGlow = null;
      }
      this.recLit = Math.max(0, this.recLit - dt);
      this.passStampDuration = Math.max(0, this.passStampDuration - dt);
      if (this.passStampDuration === 0) this.passStamp = false;

      this.verdictDuration = Math.max(0, this.verdictDuration - dt);

      // Confetti updates
      this.confetti = this.confetti.filter(p => (p.life -= dt) > 0);
      for (const p of this.confetti) {
        p.x += p.vx * dt;
        p.y += p.vy * dt;
      }
    }

    R(x, y, w, h, c) {
      this.ctx.fillStyle = c;
      this.ctx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
    }

    spr(c, x, y, s = 2, flip = false) {
      const w = c.width * s, h = c.height * s;
      if (flip) {
        this.ctx.save();
        this.ctx.translate(Math.round(x) + w, Math.round(y));
        this.ctx.scale(-1, 1);
        this.ctx.drawImage(c, 0, 0, w, h);
        this.ctx.restore();
      } else {
        this.ctx.drawImage(c, Math.round(x), Math.round(y), w, h);
      }
    }

    T(s, x, y, size, col, font = '"JetBrains Mono", monospace', align = 'left') {
      this.ctx.font = size + 'px ' + font;
      this.ctx.fillStyle = col;
      this.ctx.textBaseline = 'top';
      this.ctx.textAlign = align;
      this.ctx.fillText(s, Math.round(x), Math.round(y));
    }

    drawBubble(x, y, w, h, col, tx, ty) {
      this.R(x + 3, y + 3, w, h, 'rgba(15,18,38,0.25)');
      this.R(x - 2, y - 2, w + 4, h + 4, '#0F1226');
      this.R(x, y, w, h, col);
      this.R(tx - 3, ty - 6, 6, 6, col);
    }

    draw() {
      const ctx = this.ctx;
      ctx.save();

      // Screen shake on check failure
      if (this.shakeDuration > 0) {
        const sx = (Math.random() * 6 - 3) | 0;
        const sy = (Math.random() * 4 - 2) | 0;
        ctx.translate(sx, sy);
      }

      // 1. Wall and Floor
      this.R(0, 0, W, 180, '#F3EAD7');
      this.R(0, 120, W, 46, '#EBDDBF');
      this.R(0, 164, W, 8, '#D9C9A8');
      this.R(0, 172, W, 110, '#CDB892');
      for (let x = 0; x < W; x += 40) this.R(x, 172, 2, 108, '#C2AC84');
      this.R(0, 214, W, 2, '#C2AC84');

      // 2. Whiteboard (x: 16, y: 18)
      this.R(16, 18, 140, 78, '#0F1226');
      this.R(18, 20, 136, 74, '#FFFFFF');
      this.R(24, 96, 124, 4, '#8A8FA8');
      this.T('IDEAS', 24, 24, 8, '#0F1226', '"Pixelify Sans", monospace');

      // Sticky notes on whiteboard
      this.R(24, 38, 36, 22, '#EF6F5E');
      this.R(68, 38, 36, 22, '#F2B63D');
      this.R(112, 38, 36, 22, '#4DA3FF');
      for (let i = 0; i < 4; i++) {
        this.R(24, 66 + i * 6, (i * 24 + 40) % 90, 2, '#C9C4D6');
      }

      // Spec card on board
      if (this.spec) {
        this.R(100, 30, 48, 38, '#FFFDF8');
        this.R(98, 28, 52, 42, '#0F1226');
        this.R(100, 30, 48, 38, '#FFFDF8');
        this.R(100, 30, 48, 4, '#E5322D');
        this.T('SPEC', 104, 36, 7, '#0F1226', '"Pixelify Sans", monospace');
        const shortSpec = this.spec.slice(0, 14);
        this.T(shortSpec, 104, 46, 6, '#454963');
      }

      // 3. Skyline Window (x: 196, y: 14)
      this.R(196, 14, 124, 86, '#0F1226');
      this.R(200, 18, 116, 78, '#BFE3F5');
      this.R(200, 56, 116, 40, '#F9DCC4');
      this.R(296, 24, 10, 10, '#FFF1A8'); // sun / moon

      // Skyline buildings
      WB_BUILDINGS.forEach((b, bi) => {
        const [bx, bw, bh, bc] = b, by = 96 - bh;
        this.R(bx, by, bw, bh, bc);
        for (let c = 0; c < Math.floor((bw - 4) / 4); c++) {
          for (let r = 0; r < Math.floor((bh - 4) / 5); r++) {
            const lit = (bi * 7 + r * 3 + c * 5) % 3 === 0;
            this.R(bx + 3 + c * 4, by + 3 + r * 5, 2, 3, lit ? '#FFF1A8' : 'rgba(15,18,38,0.3)');
          }
        }
      });
      this.R(257, 18, 3, 78, '#0F1226'); // Window mullion vertical
      this.R(200, 56, 116, 3, '#0F1226'); // Window mullion horizontal

      // 4. Engineer Desk & Station (x: 150, y: 156)
      const engBob = this.typing ? (Math.floor(this.t * 7) % 2) : 0;
      this.spr(this.facepalm ? SP.eng.react : SP.eng.idle, this.engPos.x, this.engPos.y + engBob, 2, false);

      this.R(150, 156, 176, 10, '#8B5E3C');
      this.R(150, 156, 176, 2, '#B07B4F');
      this.R(154, 166, 168, 26, '#6F4A2E');
      this.R(160, 172, 70, 14, '#5E3E26');
      this.R(240, 172, 70, 14, '#5E3E26');
      this.R(190, 178, 10, 2, '#C9B27C');
      this.R(270, 178, 10, 2, '#C9B27C');
      this.R(150, 192, 176, 4, 'rgba(15,18,38,0.18)');

      // Monitor & Screen
      this.R(228, 146, 10, 10, '#2B3358');
      this.R(200, 102, 66, 44, '#0F1226');
      this.R(201, 103, 64, 42, '#2B3358');

      // Monitor Screen content
      const sx = 203, sy = 105, sw = 60, sh = 36;
      this.R(sx, sy, sw, sh, '#14183A');
      if (this.typing) {
        const cols = ['#4DA3FF', '#F2B63D', '#2FB36B', '#EF6F5E', '#C9C4D6'];
        const off = (this.t * 14) % 5;
        for (let i = 0; i < 7; i++) {
          const y = sy + 2 + i * 5 - off;
          if (y < sy || y > sy + sh - 3) continue;
          const w = 10 + ((i + Math.floor(this.t * 4)) * 17) % 36;
          this.R(sx + 3, y, Math.min(w, sw - 6), 2, cols[(i + Math.floor(this.t)) % 5]);
        }
      } else if (this.passStamp) {
        this.R(sx, sy, sw, sh, '#FFFDF8');
        this.R(sx, sy, sw, 6, '#2E8F8B');
        this.T('PASS', sx + 18, sy + 14, 10, '#1B8548', '"Pixelify Sans", monospace');
      } else {
        if (Math.floor(this.t * 2) % 2 === 0) this.T('>_', sx + 4, sy + 4, 8, '#8CF0B4');
      }

      // Keyboard & Laptop
      this.R(204, 152, 50, 4, '#C9C4D6');
      if (this.typing) {
        for (let i = 0; i < 6; i++) {
          if ((Math.floor(this.t * 12) + i) % 3 === 0) this.R(206 + i * 8, 152, 3, 2, '#FFFFFF');
        }
      }
      this.spr(SP.laptop, 278, 136, 2, false);

      // 5. Shelf, Flight Recorder & Alarm Lamp
      this.R(414, 78, 64, 5, '#8B5E3C');
      this.R(420, 83, 4, 10, '#6F4A2E');
      this.R(468, 83, 4, 10, '#6F4A2E');

      // Flight recorder black box
      const recOn = this.recLit > 0 || (Math.floor(this.t * 2) % 2 === 0 && this.statusText === 'building');
      this.spr(recOn ? SP.rec.on : SP.rec.dim, 428, 48, 2, false);

      // Alarm Lamp
      if (this.alarmGlow) {
        ctx.fillStyle = this.alarmGlow;
        ctx.fillRect(436, 10, 36, 36);
      }
      this.R(446, 22, 12, 12, '#2B3358');
      this.R(448, 24, 8, 8, this.alarmColor);
      this.R(450, 34, 4, 4, '#2B3358');

      // 6. Financial Chart Board (x: 398, y: 132)
      this.R(402, 176, 3, 40, '#6F4A2E');
      this.R(458, 176, 3, 40, '#6F4A2E');
      this.R(398, 132, 66, 52, '#0F1226');
      this.R(400, 134, 62, 48, '#FFFDF8');
      this.R(404, 176, 54, 1, '#8A8FA8');

      const barHeights = [14, 26, 18, 34];
      const barCols = ['#4DA3FF', '#2FB36B', '#F2B63D', '#EF6F5E'];
      for (let i = 0; i < 4; i++) {
        this.R(408 + i * 13, 176 - barHeights[i], 9, barHeights[i], barCols[i]);
      }
      this.T('CFO', 404, 137, 7, '#5E3A63', '"Pixelify Sans", monospace');

      // 7. Characters
      const walkBob = x => Math.floor(x / 6) % 2;

      // Founder
      const founderBob = Math.floor(this.t * 2) % 2;
      this.spr(this.founderReact ? SP.founder.react : SP.founder.idle, this.founderPos.x, this.founderPos.y + founderBob, 2, false);

      // Tester
      const testerMoving = Math.abs(this.testerPos.x - this.testerTarget) > 1;
      const testerBob = testerMoving ? walkBob(this.testerPos.x) : (Math.floor(this.t * 2) % 2);
      this.spr(this.testerReact ? SP.tester.react : SP.tester.idle, this.testerPos.x, this.testerPos.y + testerBob, 2, testerMoving);

      if (this.testerClipboard) {
        this.R(this.testerPos.x + 28, this.testerPos.y + testerBob + 18, 10, 13, '#7A4E2D');
        this.R(this.testerPos.x + 30, this.testerPos.y + testerBob + 20, 6, 9, '#FFFDF8');
      }

      // CFO
      if (this.cfoVisible) {
        const cfoMoving = Math.abs(this.cfoPos.x - this.cfoTarget) > 1;
        const cfoBob = cfoMoving ? walkBob(this.cfoPos.x) : (Math.floor(this.t * 2) % 2);
        this.spr(this.cfoReact ? SP.cfo.react : SP.cfo.idle, this.cfoPos.x, this.cfoPos.y + cfoBob, 2, false);
      }

      // 8. Bubbles & Overlays
      // Founder Idea Bubble
      if (this.founderBubble) {
        const txt = this.founderBubble.slice(0, 36);
        this.drawBubble(20, 106, 126, 36, '#FFFFFF', 66, 150);
        this.T(txt.slice(0, 18), 26, 111, 8, '#0F1226');
        if (txt.length > 18) {
          this.T(txt.slice(18, 36), 26, 123, 8, '#0F1226');
        }
      }

      // Error Bubble
      if (this.errorBubble) {
        this.drawBubble(260, 94, 96, 32, '#FFE9E6', 250, 128);
        this.T('FAIL', 265, 98, 8, '#CF2A25', '"Pixelify Sans", monospace');
        this.T(this.errorBubble.slice(0, 16), 265, 110, 7, '#0F1226');
      }

      // Crash Report Card
      if (this.crashReport) {
        const cx = 330, cy = 96;
        this.R(cx + 3, cy + 3, 92, 54, 'rgba(15,18,38,0.25)');
        this.R(cx - 2, cy - 2, 96, 58, '#0F1226');
        this.R(cx, cy, 92, 54, '#FFFDF8');
        this.R(cx, cy, 92, 10, '#CF2A25');
        this.T('CRASH REPORT', cx + 4, cy + 1, 7, '#FFFFFF', '"Pixelify Sans", monospace');
        this.T('ROOT: ' + this.crashReport.root, cx + 4, cy + 15, 6, '#0F1226');
        this.T('FIX: ' + this.crashReport.change, cx + 4, cy + 30, 6, '#1B8548');
      }

      // Patch Tag
      if (this.patchTag) {
        this.T(this.patchTag, 236, 92, 9, '#1B8548', '"Pixelify Sans", monospace');
      }

      // PASS Stamp
      if (this.passStamp) {
        ctx.save();
        ctx.translate(290, 119);
        ctx.rotate(-8 * Math.PI / 180);
        this.R(2, 2, 42, 16, 'rgba(15,18,38,0.3)');
        this.R(-21, -8, 42, 16, '#1B8548');
        this.T('PASS', 0, -5, 10, '#FFFFFF', '"Pixelify Sans", monospace', 'center');
        ctx.restore();
      }

      // Giant Rotated Verdict Stamp
      if (this.verdictStamp && this.verdictDuration > 0) {
        const col = this.verdictStamp === 'BUILD' ? '#1B8548' : this.verdictStamp === 'KILL' ? '#CF2A25' : '#F2B63D';
        const txtCol = this.verdictStamp === 'PIVOT' ? '#0F1226' : '#FFFFFF';
        ctx.save();
        ctx.translate(350, 56);
        ctx.rotate(-9 * Math.PI / 180);
        this.R(-42, -16, 90, 34, 'rgba(15,18,38,0.35)');
        this.R(-44, -18, 90, 34, '#0F1226');
        this.R(-42, -16, 86, 30, col);
        ctx.strokeStyle = txtCol;
        ctx.lineWidth = 1;
        ctx.strokeRect(-38.5, -12.5, 79, 23);
        this.T(this.verdictStamp, 2, -8, 16, txtCol, '"Pixelify Sans", monospace', 'center');
        ctx.restore();
      }

      // Confetti
      for (const p of this.confetti) {
        this.R(p.x, p.y, 3, 3, p.c);
      }

      ctx.restore();
    }
  }

  window.PixelOffice = PixelOffice;
})();

/* Pocket Startup UI Controller
   Plain JS, offline-first, no frameworks.
   Interacts with /api endpoints and streams SSE events to PixelOffice.
*/
(function () {
  const $ = (id) => document.getElementById(id);
  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[c]));

  const fmt = (v, d = 2) => (v === null || v === undefined ? 'n/a' : Number(v).toFixed(d));
  const usd = (v) => (v === null || v === undefined ? 'n/a' : '$' + Number(v).toFixed(6));

  const office = new window.PixelOffice($('office'));

  const S = {
    mode: 'baseline',
    mock: false,
    runId: null,
    es: null,
    replay: false,
    cfg: {},
    running: false,
    lastRec: null,
    founderCohort: 'held_out',
    verdictFounder: 'a',
  };

  async function api(path, opts = {}) {
    const res = await fetch(path, opts);
    const data = await res.json().catch(() => ({}));
    if (!res.ok) {
      throw new Error(data.detail || res.statusText || 'API request failed');
    }
    return data;
  }

  function chip(tag) {
    if (!tag) return '';
    const t = String(tag).trim();
    let cls = 'chip';
    if (t.includes('MEASURED')) cls += ' meas';
    else if (t.includes('COMPUTED')) cls += ' comp';
    else if (t.includes('ASSUMED')) cls += ' ass';
    else if (t.includes('USER-PROVIDED')) cls += ' user';
    else if (t.includes('MOCK')) cls += ' mock';
    else if (t.includes('FOUND')) cls += ' found';
    return `<span class="${cls}">${esc(t)}</span>`;
  }

  /* ================= Navigation & Tabs ================= */
  const tabs = Array.from(document.querySelectorAll('[role=tab]'));
  function selectTab(tabEl) {
    tabs.forEach((t) => {
      const active = t === tabEl;
      t.setAttribute('aria-selected', active);
      const panelId = t.getAttribute('aria-controls');
      const panel = $(panelId);
      if (panel) panel.hidden = !active;
    });

    const name = tabEl.id.replace('t-', '');
    if (name === 'cost') renderCostRadar();
    else if (name === 'verdict') renderVerdict();
    else if (name === 'founder') loadFounderDefaults();
    else if (name === 'plan') renderPlan();
  }

  tabs.forEach((t) => {
    t.addEventListener('click', () => selectTab(t));
  });

  function openTab(name) {
    const el = $('t-' + name);
    if (el) selectTab(el);
  }

  /* ================= Top Bar Controls ================= */
  $('mode-baseline').addEventListener('click', () => setMode('baseline'));
  $('mode-improved').addEventListener('click', () => setMode('improved'));

  function setMode(m) {
    S.mode = m;
    $('mode-baseline').setAttribute('aria-pressed', m === 'baseline');
    $('mode-improved').setAttribute('aria-pressed', m === 'improved');
  }

  $('mock-toggle').addEventListener('change', (e) => {
    S.mock = e.target.checked;
    updateBanner();
  });

  function updateBanner() {
    const bannerEl = $('banner');
    if (S.replay) {
      bannerEl.className = 'banner show banner-replay';
      bannerEl.textContent = 'REPLAY: Showing recorded run events from events.json. No real API calls are occurring.';
    } else if (S.mock) {
      bannerEl.className = 'banner show banner-mock';
      bannerEl.textContent = 'MOCK MODE: Using offline scripted MockLLM. Mock runs are labelled MOCK and never enter metrics.';
    } else {
      bannerEl.className = 'banner';
      bannerEl.textContent = '';
    }
  }

  /* ================= Run & Event Stream ================= */
  function resetRunUi() {
    $('p-log').innerHTML = '';
    $('k-cost').textContent = '$0.000000';
    $('k-tokens').textContent = '0';
    $('k-attempt').textContent = `0 of ${S.cfg.max_attempts || 4}`;
    $('k-rails').textContent = 'all clear';
    $('k-rails').className = '';
    $('approve-btn').disabled = true;
    $('open-app-link').hidden = true;
    $('built-app-card').hidden = true;
    $('status-text').textContent = 'ready';
  }

  function appendLog(t, text, type = 'info') {
    const logBox = $('p-log');
    const entry = document.createElement('div');
    entry.className = `log-entry ${type}`;
    const timeStr = typeof t === 'number' ? `${t.toFixed(1)}s` : '0.0s';
    entry.innerHTML = `<span class="time">${timeStr}</span> <span>${esc(text)}</span>`;
    logBox.appendChild(entry);
    logBox.scrollTop = logBox.scrollHeight;
  }

  function appendAutopsy(d) {
    const logBox = $('p-log');
    const card = document.createElement('div');
    card.className = 'autopsy-card';
    card.innerHTML = `
      <h5>CRASH REPORT (Autopsy)</h5>
      <div><strong>Root cause:</strong> ${esc(d.root_cause || 'unknown')}</div>
      <div><strong>Evidence:</strong> ${esc((d.evidence || []).join(' | '))}</div>
      <div><strong>Rule change:</strong> ${esc(d.recommended_prompt_change || 'none')}</div>
    `;
    logBox.appendChild(card);
    logBox.scrollTop = logBox.scrollHeight;
  }

  function handleServerEvent(ev) {
    const { type, data: d, t } = ev;
    office.handle(type, d);

    if (d && d._cost !== undefined) {
      $('k-cost').textContent = usd(d._cost);
      $('k-tokens').textContent = d._tokens || 0;
    }

    switch (type) {
      case 'run_started':
        $('status-text').textContent = 'running';
        appendLog(t, `Run started: "${d.idea}" (${d.mode}, budget $${d.budget_usd}${d.mock ? ', MOCK' : ''})`);
        break;

      case 'plan':
        appendLog(t, `Plan ready: ${d.product_name} (${d.template})`);
        break;

      case 'attempt_started':
        $('k-attempt').textContent = `${d.n} of ${d.of}`;
        appendLog(t, `Attempt ${d.n} of ${d.of} started`);
        break;

      case 'code_written':
        appendLog(t, `Code generated: ${d.bytes} bytes of HTML/JS`);
        break;

      case 'check_started':
        appendLog(t, `Running browser acceptance checks in headless Chromium...`);
        break;

      case 'check_failed':
        appendLog(t, `CHECK FAILED: ${d.test} (Expected: ${d.expected}, Got: ${d.actual})`, 'bad');
        break;

      case 'autopsy':
        appendLog(t, `Autopsy completed: ${d.root_cause}`, 'warn');
        appendAutopsy(d);
        break;

      case 'retry':
        appendLog(t, `Retrying: attempting revision ${d.next}`, 'warn');
        break;

      case 'check_passed':
        appendLog(t, `ALL CHECKS PASSED on attempt ${d.attempt}!`, 'good');
        break;

      case 'rail_fired':
        appendLog(t, `TRUST RAIL FIRED: ${d.rail}. ${d.detail}`, 'bad');
        $('k-rails').textContent = `fired: ${d.rail}`;
        $('k-rails').className = 'fail';
        break;

      case 'awaiting_approval':
        appendLog(t, `Build passing. Awaiting human approval gate.`, 'warn');
        if (!S.replay) $('approve-btn').disabled = false;
        $('status-text').textContent = 'awaiting approval';
        break;

      case 'approved':
        appendLog(t, `Human approval received. Build released ✔`, 'good');
        $('approve-btn').disabled = true;
        $('status-text').textContent = 'approved';
        break;

      case 'metrics_ready':
        appendLog(t, `Live metrics updated from trace`);
        break;

      case 'verdict_ready':
        appendLog(t, `Verdict evaluated: ${d.verdict} (${d.layer_verdicts ? Object.entries(d.layer_verdicts).map(([k,v]) => `${k}:${v}`).join(', ') : ''})`, d.verdict === 'BUILD' ? 'good' : 'warn');
        break;

      case 'run_finished':
        const outcome = d.success ? 'SUCCESS' : 'FAILED';
        appendLog(t, `Run finished: ${outcome} in ${d.attempts} attempts. Cost: ${usd(d.cost_usd)}, Tokens: ${d.tokens}`, d.success ? 'good' : 'bad');
        onRunFinished(d);
        break;
    }
  }

  function onRunFinished(d) {
    S.running = false;
    $('run-btn').disabled = false;
    $('kill-btn').disabled = true;
    $('status-text').textContent = d.success ? 'finished (passed)' : 'finished (failed)';

    if (d.success && d.run_id) {
      const appUrl = `/api/runs/${encodeURIComponent(d.run_id)}/app`;
      $('built-app-iframe').src = appUrl;
      $('built-app-card').hidden = false;
      $('open-app-link').hidden = false;
      $('open-app-link').href = appUrl;
    }

    refreshReplayList();
  }

  function startSseListener(runId, isReplay) {
    if (S.es) S.es.close();

    S.runId = runId;
    S.replay = isReplay;
    S.running = true;
    resetRunUi();
    updateBanner();

    $('run-btn').disabled = true;
    $('kill-btn').disabled = isReplay;
    $('status-text').textContent = isReplay ? 'replaying' : 'running';

    const es = new EventSource(`/api/runs/${encodeURIComponent(runId)}/events`);
    S.es = es;

    es.addEventListener('ev', (m) => {
      try {
        const ev = JSON.parse(m.data);
        handleServerEvent(ev);
      } catch (err) {
        console.error('SSE parse error', err);
      }
    });

    es.addEventListener('end', () => {
      es.close();
      S.running = false;
      $('kill-btn').disabled = true;
      $('run-btn').disabled = false;
      $('status-text').textContent = 'completed';
    });

    es.onerror = () => {
      es.close();
      S.running = false;
      $('kill-btn').disabled = true;
      $('run-btn').disabled = false;
    };
  }

  $('run-btn').addEventListener('click', async () => {
    const idea = $('idea-input').value.trim();
    if (!idea) {
      $('idea-input').focus();
      return;
    }

    const budgetVal = parseFloat($('budget-input').value) || null;
    try {
      $('run-btn').disabled = true;
      const res = await api('/api/runs', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          idea,
          mode: S.mode,
          budget_usd: budgetVal,
          mock: S.mock,
        }),
      });

      openTab('log');
      startSseListener(res.run_id, false);
    } catch (err) {
      alert(`Could not launch run: ${err.message}`);
      $('run-btn').disabled = false;
    }
  });

  $('kill-btn').addEventListener('click', async () => {
    if (!S.runId) return;
    try {
      await api(`/api/runs/${encodeURIComponent(S.runId)}/kill`, { method: 'POST' });
      appendLog(0, 'Kill switch activated by operator.', 'bad');
    } catch (err) {
      console.warn('Kill failed', err);
    }
  });

  $('approve-btn').addEventListener('click', async () => {
    if (!S.runId) return;
    try {
      await api(`/api/runs/${encodeURIComponent(S.runId)}/approve`, { method: 'POST' });
      $('approve-btn').disabled = true;
    } catch (err) {
      alert(`Approval error: ${err.message}`);
    }
  });

  $('replay-btn').addEventListener('click', async () => {
    const targetRun = $('replay-select').value;
    if (!targetRun) return;

    const speed = $('replay-speed').value || '1';
    try {
      const res = await api(`/api/replay/${encodeURIComponent(targetRun)}?speed=${speed}`, { method: 'POST' });
      openTab('log');
      startSseListener(res.replay_id, true);
    } catch (err) {
      alert(`Replay failed: ${err.message}`);
    }
  });

  async function refreshReplayList() {
    try {
      const runs = await api('/api/runs');
      const sel = $('replay-select');
      const cur = sel.value;
      sel.innerHTML = '<option value="">Select a saved run to replay...</option>' +
        runs.map((r) => {
          const mockTag = r.mock ? '[MOCK] ' : '';
          const passTag = r.success ? 'PASS' : 'FAIL';
          const snippet = (r.idea || '').slice(0, 32);
          return `<option value="${esc(r.run_id)}">${mockTag}${esc(r.run_id)} (${passTag}) - ${esc(snippet)}</option>`;
        }).join('');
      sel.value = cur;
    } catch (_) {
      // Offline fallback
    }
  }

  /* ================= Cost Radar Tab ================= */
  async function renderCostRadar() {
    const container = $('p-cost');
    try {
      const m = await api('/api/metrics');
      const exp = m.experiment || {};

      let html = `<h3>Cost Radar: Baseline vs Improved</h3>`;

      if (!exp.tuning && !exp.held_out) {
        html += `<p>No experiment metrics found. Run <code>python -m experiments.ab</code> to populate A/B metrics.</p>`;
        container.innerHTML = html;
        return;
      }

      // Comparison Table
      html += `
        <div class="metric-card">
          <h4>Held-Out & Tuning Sets (Before / After)</h4>
          <table class="metric-table">
            <thead>
              <tr>
                <th>Cohort</th>
                <th>Arm</th>
                <th>First-Attempt Pass</th>
                <th>Eventual Success</th>
                <th>Cost / Success</th>
                <th>Retry Tax</th>
                <th>Median Latency</th>
              </tr>
            </thead>
            <tbody>
      `;

      ['held_out', 'tuning', 'combined'].forEach((cohort) => {
        const cData = exp[cohort];
        if (!cData) return;
        ['baseline', 'improved'].forEach((arm) => {
          const r = cData[arm];
          if (!r) return;
          const firstPassStr = `${r.first_attempt_pass_count}/${r.n_runs} ${chip(r.first_attempt_pass_rate_tag || 'MEASURED')}`;
          const successStr = `${r.success_count}/${r.n_runs} ${chip(r.success_rate_tag || 'MEASURED')}`;
          const cpsStr = r.cost_per_success != null ? `$${r.cost_per_success.toFixed(6)} ${chip(r.cost_per_success_tag || 'COMPUTED')}` : 'n/a';
          const taxStr = r.retry_tax != null ? `${r.retry_tax.toFixed(1)}% ${chip(r.retry_tax_tag || 'COMPUTED')}` : 'n/a';
          const latStr = r.median_latency_seconds != null ? `${r.median_latency_seconds.toFixed(1)}s ${chip(r.median_latency_tag || 'MEASURED')}` : 'n/a';

          html += `
            <tr>
              <td><strong>${esc(cohort)}</strong></td>
              <td>${esc(arm)}</td>
              <td>${firstPassStr}</td>
              <td>${successStr}</td>
              <td class="num">${cpsStr}</td>
              <td class="num">${taxStr}</td>
              <td class="num">${latStr}</td>
            </tr>
          `;
        });
      });

      html += `
            </tbody>
          </table>
        </div>
      `;

      // Statistical Headline & Note
      const headline = m.statistical_headline || {};
      const fisherStr = headline.fisher_exact_p_value || exp.fisher_exact_p_value || 'p < 0.0001';
      html += `
        <div class="note-box" style="margin-top: 14px;">
          <p><strong>First-Attempt Rate:</strong> Jumped from 1/20 to 16/20 on held-out ideas (${fisherStr} ${chip('COMPUTED')}).</p>
          <p style="color: var(--ink2); font-weight: 700; margin-top: 6px;">
            Note: eventual success did not differ significantly.
          </p>
          <p style="font-size: 12px; margin-top: 6px; color: var(--ink2);">
            <em>Limitation: The remaining held-out failures come from two pool-style ideas (tip pools) where the idea's framing conflicts with the per-person contract.</em>
          </p>
        </div>
      `;

      container.innerHTML = html;
    } catch (err) {
      container.innerHTML = `<p style="color: var(--red);">Failed to load Cost Radar: ${esc(err.message)}</p>`;
    }
  }

  /* ================= Verdict Tab ================= */
  async function renderVerdict() {
    const container = $('p-verdict');
    const founderKey = S.verdictFounder || 'a';

    try {
      const v = await api(`/api/verdict?founder=${founderKey}&cohort=${S.founderCohort}`);
      const overall = v.verdict || 'PIVOT';

      let html = `
        <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; flex-wrap: wrap; gap: 8px;">
          <h3>Deterministic Verdict Engine</h3>
          <div class="seg-group">
            <button class="seg-btn" id="v-founder-a" aria-pressed="${founderKey === 'a'}">Founder A</button>
            <button class="seg-btn" id="v-founder-b" aria-pressed="${founderKey === 'b'}">Founder B</button>
          </div>
        </div>

        <div class="verdict-hero">
          <span style="font-size: 11px; font-weight: 700; text-transform: uppercase; color: var(--ink2);">Evaluated Verdict (Cohort: ${esc(S.founderCohort)})</span>
          <div class="stamp ${overall}">${overall}</div>
          <p style="font-size: 12px; color: var(--ink2); margin: 0;">Code-evaluated across 4 deterministic gates. Zero LLMs involved.</p>
        </div>

        <h4>Gate Outcomes</h4>
        <div class="layer-list">
      `;

      const layers = v.layer_verdicts || {};
      for (const [layer, lVerd] of Object.entries(layers)) {
        html += `
          <div class="layer-row">
            <span><strong>${esc(layer.toUpperCase())}</strong></span>
            <span class="chip ${lVerd === 'BUILD' ? 'meas' : lVerd === 'KILL' ? 'comp' : 'ass'}">${lVerd}</span>
          </div>
        `;
      }
      html += `</div>`;

      // Reasons with source tags
      html += `<h4 style="margin-top: 14px;">Rule Explanations &amp; Source Tags</h4><ul class="reason-list">`;
      (v.reasons || []).forEach((r) => {
        html += `<li class="reason-item">${esc(r)}</li>`;
      });
      html += `</ul>`;

      // Cheapest next experiment
      if (v.cheapest_next_experiment) {
        const exp = v.cheapest_next_experiment;
        html += `
          <div class="next-exp-box">
            <h4>Cheapest Next Experiment</h4>
            <p><strong>Action:</strong> ${esc(exp.experiment || 'None')}</p>
            <p><strong>Cost:</strong> ${esc(exp.estimated_cost || '0 INR')} ${chip('ASSUMED')}</p>
            <p><strong>Lever:</strong> ${esc(exp.lever || 'Validate demand')}</p>
          </div>
        `;
      }

      container.innerHTML = html;

      // Event listeners for A / B switcher
      $('v-founder-a').addEventListener('click', () => {
        S.verdictFounder = 'a';
        renderVerdict();
      });
      $('v-founder-b').addEventListener('click', () => {
        S.verdictFounder = 'b';
        renderVerdict();
      });
    } catch (err) {
      container.innerHTML = `<p style="color: var(--red);">Verdict evaluation failed: ${esc(err.message)}</p>`;
    }
  }

  /* ================= Founder Intake Form Tab ================= */
  function loadFounderDefaults() {
    // If not filled, pre-populate Founder A baseline values
    if (!$('f-target-user').value) {
      $('f-target-user').value = 'Office teams who run shared coffee and lunch orders';
      $('f-payer').value = 'Office managers';
      $('f-goal').value = 'Per-person bill and tip splitting for office group orders';
      $('f-channel').value = 'Direct outreach to office managers';
      $('f-demand').value = 'interviews';
      $('f-budget').value = '350000';
      $('f-hours').value = '40';
      $('f-skills').value = 'b2b sales, python';
      $('f-price').value = '50';
    }
  }

  $('founder-form').addEventListener('submit', async (e) => {
    e.preventDefault();
    const payload = {
      target_user: $('f-target-user').value.trim(),
      payer: $('f-payer').value.trim(),
      goal: $('f-goal').value.trim(),
      first_customer_channel: $('f-channel').value.trim(),
      demand_evidence: $('f-demand').value,
      budget_inr: parseFloat($('f-budget').value) || 0,
      weekly_hours: parseFloat($('f-hours').value) || 0,
      skills: $('f-skills').value.split(',').map((s) => s.trim()).filter(Boolean),
      price_per_run_inr: parseFloat($('f-price').value) || 0,
      cohort: $('f-cohort').value,
    };

    const outBox = $('founder-verdict-result');
    outBox.innerHTML = '<p>Recomputing deterministic verdict...</p>';

    try {
      const res = await api('/api/founder/verdict', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      const overall = res.verdict || 'PIVOT';
      let outHtml = `
        <div class="verdict-hero" style="margin-top: 14px;">
          <span style="font-size: 11px; font-weight: 700; color: var(--ink2);">RECOMPUTED VERDICT</span>
          <div class="stamp ${overall}">${overall}</div>
          <div style="font-size: 12px; margin-top: 4px;">
            Gross Margin: <strong>${fmt(res.metrics_used?.gross_margin, 1)}%</strong> ${chip('COMPUTED')} |
            Runway: <strong>${fmt(res.metrics_used?.runway_months, 1)} mo</strong> ${chip('COMPUTED')}
          </div>
        </div>

        <h4>Gate Outcomes</h4>
        <div class="layer-list">
      `;

      for (const [l, v] of Object.entries(res.layer_verdicts || {})) {
        outHtml += `
          <div class="layer-row">
            <span><strong>${esc(l.toUpperCase())}</strong></span>
            <span class="chip ${v === 'BUILD' ? 'meas' : v === 'KILL' ? 'comp' : 'ass'}">${v}</span>
          </div>
        `;
      }
      outHtml += `</div><h4 style="margin-top: 10px;">Rule Explanations</h4><ul class="reason-list">`;
      (res.reasons || []).forEach((r) => {
        outHtml += `<li class="reason-item">${esc(r)}</li>`;
      });
      outHtml += `</ul>`;

      outBox.innerHTML = outHtml;
    } catch (err) {
      outBox.innerHTML = `<p style="color: var(--red);">Recomputation error: ${esc(err.message)}</p>`;
    }
  });

  /* ================= Plan Tab ================= */
  async function renderPlan() {
    const container = $('p-plan');
    try {
      const p = await api('/api/plan');
      const isReady = p.status === 'READY';

      let html = `
        <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px;">
          <h3>cfo.ai Financial Plan</h3>
          <span class="plan-status-badge ${isReady ? 'READY' : 'PENDING'}">${isReady ? 'PLAN READY' : 'PLAN PENDING'}</span>
        </div>
      `;

      if (isReady && p.plan_numbers && typeof p.plan_numbers === 'object') {
        const nums = p.plan_numbers;
        html += `
          <div class="cfo-summary-card">
            <h4>Plan Metrics (from cfo.ai)</h4>
            <table class="metric-table">
              <tbody>
                <tr><td>Price per run</td><td class="num">₹${fmt(nums.price_per_run_inr)} ${chip('USER-PROVIDED')}</td></tr>
                <tr><td>Gross Margin</td><td class="num">${fmt(nums.gross_margin_percent, 1)}% ${chip('COMPUTED')}</td></tr>
                <tr><td>Runway</td><td class="num">${fmt(nums.runway_months, 1)} months ${chip('COMPUTED')}</td></tr>
                <tr><td>Break-even customers</td><td class="num">${nums.breakeven_customers || 'n/a'} ${chip('COMPUTED')}</td></tr>
              </tbody>
            </table>
          </div>
        `;
      } else {
        html += `
          <div class="note-box" style="margin-bottom: 14px;">
            <p><strong>Notice:</strong> cfo.ai financial plan is currently PENDING. Paste <code>evidence/cfo/cfo_input.md</code> into cfo.ai to generate plan numbers.</p>
          </div>
        `;
      }

      if (p.plan_summary && p.plan_summary !== 'PENDING') {
        html += `
          <div class="cfo-summary-card">
            <h4>Executive Summary</h4>
            <div style="white-space: pre-wrap; font-size: 13px; line-height: 1.45;">${esc(p.plan_summary)}</div>
          </div>
        `;
      }

      // Evidence links and exports
      html += `<h4>Evidence &amp; Artifacts</h4><div class="evidence-links-list">`;
      html += `<a class="btn btn-sm" href="/evidence/cfo/cfo_input.md" target="_blank" rel="noopener">View cfo_input.md</a>`;

      (p.exports || []).forEach((f) => {
        html += `<a class="btn btn-sm" href="/evidence/cfo/${encodeURIComponent(f)}" target="_blank" rel="noopener">${esc(f)}</a>`;
      });
      html += `</div>`;

      container.innerHTML = html;
    } catch (err) {
      container.innerHTML = `<p style="color: var(--red);">Failed to load plan: ${esc(err.message)}</p>`;
    }
  }

  /* ================= Boot Initialization ================= */
  (async function boot() {
    try {
      S.cfg = await api('/api/config');
      if (S.cfg.mock) {
        S.mock = true;
        $('mock-toggle').checked = true;
      }
      if (S.cfg.default_budget_usd) {
        $('budget-input').value = S.cfg.default_budget_usd;
      }
    } catch (_) {
      S.cfg = {};
    }

    updateBanner();
    refreshReplayList();
    loadFounderDefaults();
  })();
})();

